SELECT p.id, p.name, p.description, p.status, p.user_id, p.create_time, p.update_time,
       (SELECT COUNT(*) FROM attachments a WHERE a.source = 'project' AND a.biz_id = p.id) AS attachment_count
FROM projects p
WHERE p.user_id = #{userId}

    AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR p.description LIKE CONCAT('%', #{keyword}, '%'))


    AND p.status = #{status}

ORDER BY p.id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM projects
WHERE user_id = #{userId}

    AND (name LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))


    AND status = #{status}
